mapper.select:
select * from sys_notice
where `delete` = 0
and title like concat('%',#{title},'%')
and notice_type = #{noticeType}
and level = #{level}
and publish_scope = #{publishScope}
and status = #{status}
and publish_time >= #{beginTime}
and publish_time <= #{endTime}
order by is_top desc, publish_time desc, notice_id desc

mapper.update:
update sys_notice
title = #{title}, content = #{content}, notice_type = #{noticeType}, level = #{level}, publish_scope = #{publishScope}, status = #{status}, is_top = #{isTop}, need_confirm = #{needConfirm}, publish_time = #{publishTime}, expire_time = #{expireTime}, route_path = #{routePath}, remark = #{remark}, `delete` = #{delete}, update_by = #{updateBy}, update_time = now()
where notice_id = #{noticeId}

mapper.select:
select count(*)
from sys_notice n
where n.`delete` = 0
  and n.status = 'PUBLISHED'
  and (n.publish_scope = 'ALL'
       or n.notice_id in (
           select rel.notice_id from sys_notice_group_rel rel
           inner join sys_notice_group_member mem on mem.group_id = rel.group_id
           where mem.user_id = #{userId}
       )
       or n.notice_id in (
           select user_rel.notice_id from sys_notice_user_rel user_rel
           where user_rel.user_id = #{userId}
       ))
  and not exists (
      select 1 from sys_notice_read r
      where r.notice_id = n.notice_id
        and r.user_id = #{userId}
        and r.read_time is not null
  )
